(async function(){
'use strict';
const D=SG_DATA,C=SG_CORE,S=SG_STORE,O=SG_OPTIONAL,R=SG_ROUTES,e=C.escape,$=s=>document.querySelector(s);
let state=C.fresh(),route='home',saveQueue=Promise.resolve(),filter={domain:'All',tier:'All',role:'All'},incoming=null,pendingImport=null,diagnostic=null,modelList=[],searchTimer=null,storageProblem=false;
const main=$('#main');
function notice(t){$('#notice').textContent=t;}
function attrs(s){return e(s);}
function badge(t,kind=''){return `<span class="badge ${kind}">${e(t)}</span>`;}
function refs(a){return a.map(id=>`<a class="source-link" href="#research/${id}">${e(id)}</a>`).join('');}
function list(a,ordered=false){const tag=ordered?'ol':'ul';return `<${tag}>${a.map(x=>`<li>${e(x)}</li>`).join('')}</${tag}>`;}
function heading(label,title,desc=''){return `<span class="eyebrow">${e(label)}</span><h1>${e(title)}</h1>${desc?`<p class="intro">${e(desc)}</p>`:''}`;}
function button(text,action,value='',cls=''){return `<button class="${cls}" data-action="${action}" data-value="${attrs(value)}">${e(text)}</button>`;}
function options(a,selected){return a.map(x=>`<option${x===selected?' selected':''}>${e(x)}</option>`).join('');}
function sourceCard(s){return `<article class="card source-card" id="source-${s.id}">${badge(s.id)}${badge(s.type,'evidence')}<h3>${e(s.title)}</h3><p>${e(s.finding)}</p><p><strong>Limits:</strong> ${e(s.limit)}</p><small>${e(s.scope)} · Published: ${e(s.date)} · Checked: ${s.checked}</small><small>${e(s.verification)}</small><p><a href="${attrs(s.url)}" target="_blank" rel="noopener noreferrer">Open primary source ↗</a></p><small>Used by: ${D.strategies.filter(x=>x.refs.includes(s.id)).map(x=>`<a href="#strategies/${x.id}">${x.id}</a>`).join(', ')||'Background / technical reference'}</small></article>`;}
function strategyCard(s,open=false){return `<details id="strategy-${s.id}" ${open?'open':''}><summary><span class="meta">${e(s.id)} · ${e(s.domain)}</span><br>${e(s.title)}</summary><div class="row between"><div>${badge('Inference','inference')}${badge('Tier '+s.tier)}${badge(s.time)}</div>${button(state.plan.includes(s.id)?'Remove from plan':'Add to plan','toggle-plan',s.id,state.plan.includes(s.id)?'':'primary')}</div><p>${e(s.goal)}</p><div class="detail-grid"><div><h3>Before starting</h3>${list(s.pre)}<h3>Practical steps</h3>${list(s.steps,true)}</div><div><h3>What can go wrong</h3><p>${e(s.failure)}</p><h3>Stop and review</h3><p>${e(s.stop)}</p><h3>Measure progress</h3><p>${e(s.metric)}</p><p>${e(s.review)}</p></div></div><p><strong>Evidence context:</strong> ${refs(s.refs)} <small>These sources inform the approach; they do not directly validate every step.</small></p><p><strong>Infrastructure:</strong> ${s.links.map(id=>`<a class="source-link" href="#infrastructure/${id}">${e(D.infrastructures.find(x=>x.id===id)?.name??id)}</a>`).join('')}</p><small>Roles: ${s.roles.map(e).join(', ')}. Suggested timescale and tier are planning heuristics.</small></details>`;}
function applySettings(){const dark=state.settings.theme==='dark'||(state.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.dataset.theme=dark?'dark':'light';document.body.classList.toggle('reduce-motion',state.settings.motion);}
function save(){state.revision++;state.updated=new Date().toISOString();const copy=structuredClone(state);saveQueue=saveQueue.then(()=>S.save(copy)).then(()=>{storageProblem=false;$('#storage-status').textContent=S.mode()==='IndexedDB'?'Saved on this device':'Memory only — export before closing';}).catch(err=>{storageProblem=true;notice('Could not persist changes. Export a JSON backup before closing. '+err.message);$('#storage-status').textContent='Save failed — export now';});return saveQueue;}
function closeDrawer(){const a=$('#sidebar');a.classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(innerWidth<=850)a.inert=true;}
function nav(){const quick=['home','strategies','plan','evidence'];$('#topnav').innerHTML=R.filter(x=>quick.includes(x.id)).map(x=>`<a href="#${x.id}" ${route===x.id?'aria-current="page"':''}>${e(x.label)}</a>`).join('');let group='';$('#sidenav').innerHTML=R.map(x=>{const h=x.group!==group?`<h2>${e(x.group)}</h2>`:'';group=x.group;return h+`<a href="#${x.id}" title="${attrs(x.hint)}" ${route===x.id?'aria-current="page"':''}>${e(x.label)}</a>`;}).join('');}
function home(){const p=C.progress(state,D),recommended=D.strategies.filter(x=>x.roles.includes(state.role)).slice(0,3);return `<div class="hero"><div>${heading('A practical field workspace','Turn a barrier into<br> a safer next step.'.replace('<br>',''),'Explore the evidence. Find an appropriate pathway. Prepare a small, reviewable improvement to children’s access and protection.')}<div class="row spaced"><a class="button primary" href="#safety">Choose a safe starting point →</a><a class="button" href="#strategies">Explore strategies</a></div></div><div class="hero-art" aria-hidden="true"><div class="circle"></div><span class="leaf">⌘</span><p>Rights at the centre.<br>Care in every step.</p><small>AFRICA-FOCUSED · LOCALLY ADAPTED</small></div></div><div class="grid"><div class="card"><span class="meta">PRACTICE BANK</span><div class="number">36 <small style="display:inline;font-size:14px">strategies</small></div><p>From everyday inclusion to institutional accountability.</p><a href="#strategies">Find an approach →</a></div><div class="card"><span class="meta">EVIDENCE & LIMITATIONS</span><div class="number">27 <small style="display:inline;font-size:14px">sources</small></div><p>Research, rights instruments and infrastructure references.</p><a href="#evidence">Inspect the evidence →</a></div><div class="card"><span class="meta">YOUR WORKSPACE</span><div class="number">${state.plan.length} <small style="display:inline;font-size:14px">selected strategies</small></div><p>${p.done} of ${p.total} planning steps marked complete.</p><a href="#plan">Continue your plan →</a></div></div><div class="row between spaced"><h2>A pathway for your role</h2><div><label for="role-home" class="sr-only">Your role</label><select id="role-home" data-setting="role">${options(C.ROLES,state.role)}</select></div></div><div class="grid">${recommended.map(s=>`<article class="card">${badge(s.domain)}<h3>${e(s.title)}</h3><p>${e(s.goal)}</p><a href="#strategies/${s.id}">Open strategy →</a></article>`).join('')}</div><div class="callout"><strong>A programme planner, not a case file.</strong> Use no names, identifying stories, documents or precise locations. No data is sent to other people automatically. For an immediate safety concern, <a href="#safety">start with the safety pathway</a>.</div><p class="muted">Curated coverage, not an all-country legal guide or a guarantee of safety. Published service references require local verification. <a href="#about">Read the scope and limitations.</a></p>`;}
function safety(){return heading('Non-negotiable foundations','Safety before action','This pathway offers general orientation. It does not assess a child or replace trained local support.')+`<div class="card"><h2>What needs attention first?</h2><div class="row">${button('Immediate danger or urgent injury','triage','urgent')}${button('Disclosure or coercion','triage','disclosure')}${button('An access barrier or discrimination','triage','access')}${button('Programme planning','triage','planning')}</div><div id="triage-result" aria-live="polite"><p>Select the closest situation. Nothing here sends a report.</p></div></div><h2>Hard boundaries</h2><div class="grid two">${[['Child-first and rights-based','No coercion, punishment, forced mediation, vigilantism or confrontation. Respect the child’s views and explain locally applicable confidentiality limits.'],['No targeting or surveillance','No child profiles, identity lists, locations, biometrics, monitoring of people or demographic risk scores. The planner accepts programme information only.'],['No automatic escalation','No auto-send, auto-report or automated case decision. Qualified humans choose safe, lawful actions after checking local requirements.'],['No reward for disclosures','Progress features track self-reported programme steps. Never reward allegations, personal stories, public exposure, contact counts or distress.']].map(([t,b])=>`<article class="card"><h3>${t}</h3><p>${b}</p></article>`).join('')}</div><h2>Before any referral or complaint</h2>${list(['Check whether the recipient, caregiver or institution is implicated. Use an independent alternative if needed.','Explain choices, consent/assent processes and reporting duties with qualified local advice; do not promise secrecy.','Agree a safe time, channel and purpose for follow-up. Do not leave identifying messages.','Stop if a step increases danger, breaches privacy, exceeds your competence or removes the child’s meaningful choice.'])}<div class="callout warning"><strong>Urgent concern:</strong> If safe, seek a trusted local emergency, health or child-protection service. This platform has no universal emergency number and cannot dispatch assistance. <a href="#infrastructure/helplines">Find the published country helpline directory</a> and verify locally.</div>${refs(['CHARTER','WHO18','CHI'])}`;}
function strategies(target){const domains=['All',...new Set(D.strategies.map(x=>x.domain))];const visible=D.strategies.filter(x=>(filter.domain==='All'||x.domain===filter.domain)&&(filter.tier==='All'||String(x.tier)===filter.tier)&&(filter.role==='All'||x.roles.includes(filter.role)));return heading('Practice bank','Choose an approach','Every strategy includes prerequisites, steps, failure modes, stop rules and measures. Steps are editorial inferences that require local review.')+`<div class="filters"><div><label for="domain-filter">Barrier or domain</label><select id="domain-filter" data-filter="domain">${options(domains,filter.domain)}</select></div><div><label for="tier-filter">Implementation tier</label><select id="tier-filter" data-filter="tier">${options(['All','0','1','2','3'],filter.tier)}</select></div><div><label for="role-filter">Role</label><select id="role-filter" data-filter="role">${options(['All',...C.ROLES],filter.role)}</select></div></div><p>${visible.length} strategies · <span class="tooltip" tabindex="0" data-tip="Editorial synthesis informed by sources; not a directly tested protocol.">What does Inference mean?</span></p>${visible.map(s=>strategyCard(s,s.id===target)).join('')||'<p>No strategies match these filters.</p>'}`;}
function plan(){const p=C.progress(state,D);return heading('Prepare → review → act → learn','My action plan','Keep this workspace free of personal case information. Checkmarks are self-reported planning progress, not evidence that children are safe.')+`<div class="row spaced"><a class="button" href="#strategies">Add strategies</a>${button('Export backup','export')}${button('Review plan','review-plan','','primary')}</div><div class="grid two"><section class="card"><h3>Readiness checks</h3><p>All four checks are required to mark the plan reviewed. These checks do not authorise action or certify safety.</p>${C.GATES.map(g=>`<label class="inline"><input type="checkbox" data-gate="${attrs(g)}" ${state.gates.includes(g)?'checked':''}><span>${e(g)}</span></label>`).join('')}<progress value="${p.readiness}" max="100" aria-label="Preparation checklist completion"></progress><small>${p.readiness}% of preparation checks acknowledged · heuristic, not a risk score</small></section><section class="card"><h3>Programme review note</h3>${badge('User-entered','user')}<label for="plan-notes">Responsibilities, resources and next review (no names or cases)</label><textarea id="plan-notes" maxlength="4000" placeholder="Example: Education team to verify an independent referral route before the next planning review.">${e(state.notes)}</textarea><small>Saved on change. Local storage and exports are not encrypted.</small>${button('Save note','save-note')}</section></div>${state.settings.engagement?`<section class="card spaced"><h3>Progress constellation</h3><p>${p.xp} practice XP · ${p.done}/${p.total} selected steps complete. XP is a self-report counter, with no ranks or rewards. Undoing a step removes its XP.</p><div class="constellation" aria-label="Selected strategy progress">${state.plan.map(id=>{const s=D.strategies.find(x=>x.id===id),done=s.steps.every((_,i)=>state.tasks[id+':'+i]);return `<span class="star ${done?'done':''}" title="${attrs(s.title)}: ${done?'all steps marked':'in progress'}">${done?'★':'☆'}</span>`;}).join('')||'<span>No strategies selected.</span>'}</div><small>Disable progress features in Settings.</small></section>`:''}<h2>Execution checklist</h2>${state.plan.length?state.plan.map(id=>{const s=D.strategies.find(x=>x.id===id);return `<section class="card spaced"><div class="row between"><h3>${e(s.title)}</h3>${button('Remove','toggle-plan',s.id)}</div>${badge('User-entered progress','user')}<p>${e(s.goal)}</p><h4>Preconditions</h4>${list(s.pre)}${s.steps.map((step,i)=>`<label class="inline"><input type="checkbox" data-task="${id}:${i}" ${state.tasks[id+':'+i]?'checked':''}><span>${e(step)}</span></label>`).join('')}<div class="callout warning"><strong>Stop:</strong> ${e(s.stop)}</div><p><strong>Watch for:</strong> ${e(s.failure)}</p><p><strong>Measure:</strong> ${e(s.metric)}</p>${refs(s.refs)}</section>`;}).join(''):'<div class="card"><p>Your plan is empty. Choose one manageable improvement from the strategy bank.</p><a href="#strategies">Find a strategy →</a></div>'}`;}
function infrastructure(target){return heading('Cross-domain service infrastructure','Find a locally usable pathway','These are published institutional references and verification prompts, not live referrals or endorsements. No child locations are mapped.')+`<div class="callout">Verify identity, safety, cost, eligibility, capacity, opening hours, language and accessibility before use. National coverage does not mean a service is available nearby. No live service calls were made.</div><div class="filters"><div><label for="infra-query">Filter by country, region or sector</label><input id="infra-query" placeholder="For example: Kenya, legal aid, schools"></div></div><div id="infra-list">${D.infrastructures.map(x=>`<details data-infra="${attrs((x.name+' '+x.region+' '+x.country+' '+x.sector).toLowerCase())}" id="infra-${x.id}" ${x.id===target?'open':''}><summary>${e(x.name)} <span class="badge">${e(x.sector)}</span></summary><p><strong>${e(x.region)} · ${e(x.country)}</strong></p><p>${e(x.access)}</p><p><strong>Verify:</strong> ${e(x.verify)}</p><p><strong>Risk:</strong> ${e(x.risk)}</p><small>${e(x.status)} · source review ${x.checked}</small><p>${refs(x.refs)}</p><small>Connected strategies: ${D.strategies.filter(s=>s.links.includes(x.id)).map(s=>`<a href="#strategies/${s.id}">${s.id}</a>`).join(' ')||'See sector-level strategies'}</small></details>`).join('')}</div>`;}
function pathways(){return heading('Role-based pathways','Work within your role','Choose a manageable tier. Specialist authority, training, supervision and local law still govern real-world action.')+`<label for="role-path">Your role</label><select id="role-path" data-setting="role">${options(C.ROLES,state.role)}</select><h2>Suggested sequence for ${e(state.role.toLowerCase())}</h2><div class="grid">${D.strategies.filter(x=>x.roles.includes(state.role)).slice(0,9).map((x,i)=>`<article class="card"><span class="meta">STEP ${i+1} · TIER ${x.tier}</span><h3>${e(x.title)}</h3><p>${e(x.goal)}</p><a href="#strategies/${x.id}">Review requirements →</a></article>`).join('')}</div><h2>Resources and implementation tiers</h2><div class="table-wrap"><table><thead><tr><th>Tier</th><th>Suitable work</th><th>Requirements</th><th>Do not proceed when</th></tr></thead><tbody><tr><td>0 · Prepare</td><td>Accessible information; safe support orientation; personal learning</td><td>Time, public material, awareness of limits</td><td>Urgent risk needs trained response</td></tr><tr><td>1 · Coordinate</td><td>Verified referrals; access improvements; complaints preparation</td><td>Vetted partners, legal checks, independent review</td><td>Recipient is implicated or capacity absent</td></tr><tr><td>2 · Implement</td><td>Supervised school, caregiver or service programmes</td><td>Budget, training, safeguarding governance, monitoring</td><td>Training or referrals are unfunded</td></tr><tr><td>3 · Sustain</td><td>Policy reform, independent evaluation, scaling</td><td>Specialists, ethical review, accountable funding</td><td>Local results or harm checks are insufficient</td></tr></tbody></table></div><p>${badge('Heuristic')}Sequences and tiers are planning suggestions, not legal permissions or evidence rankings.</p>`;}
function maps(){return heading('Mechanisms and dependencies','Timescales & cascades','Explore what must happen first, how change may spread, and where assumptions can fail. These are editable-in-practice planning hypotheses, not forecasts.')+`<div class="timeline">${[['Now','Immediate safety, safe listening and appropriate urgent support.','S01'],['Days to weeks','Verify services, remove simple access barriers and prepare confidential review.','S27'],['Months','Implement supervised school and caregiver programmes; examine unintended effects.','S12'],['Years','Sustain funding, institutional accountability and lawful policy improvements.','S30']].map(([t,b,id])=>`<div><h3>${t}</h3><p>${b}</p><a href="#strategies/${id}">Example strategy →</a></div>`).join('')}</div><h2>Explore a possible cascade</h2><label for="cascade-select">Starting point</label><select id="cascade-select"><option value="docs">Documentation access</option><option value="school">School practice</option><option value="support">Caregiver support</option></select><div id="cascade-output" class="spaced"></div><h2>Dependency checks</h2><div class="grid two"><div class="card"><h3>Before a public information campaign</h3><p>Verify a safe service route → check provider capacity → review language and identifiability → pilot privately → publish only non-identifying material.</p></div><div class="card"><h3>Before a complaint</h3><p>Child’s views and local duties → independent advice → anti-retaliation plan → verified recipient → minimal disclosure through a safe process.</p></div><div class="card"><h3>Before scaling</h3><p>Delivery quality → child experience → adverse-effect review → recurrent budget → independent evaluation → staged expansion.</p></div><div class="card"><h3>Before data collection</h3><p>Necessity → safer existing data → ethics and lawful basis → consent/assent → referral resources → minimisation → retention and deletion.</p></div></div><p>${badge('Heuristic')}Timelines depend on context, urgency and institutional capacity. Urgent care must never wait for a programme milestone.</p>`;}
function cascade(){const x=$('#cascade-select')?.value??'docs',map={docs:['Clear registration advice','Lawful registration / certificate access','Fewer administrative barriers','More consistent school or clinic access'],school:['Supervised staff learning','More respectful school practice','Safer reporting and belonging','Improved participation'],support:['Accessible caregiver programme','Supported nonviolent practice','Potentially safer home routines','Possible sustained wellbeing']};$('#cascade-output').innerHTML=`<div class="cascade">${map[x].map((t,i)=>`${i?'<b aria-hidden="true">→</b>':''}<span>${e(t)}</span>`).join('')}</div><div class="callout"><strong>Assumptions:</strong> services accept the relevant documents; staff implement changes; children can access support safely; improvements persist. These links can fail. ${x==='support'?'Caregiver and adolescent reports may differ.':x==='school'?'Long-term Good School Toolkit follow-up did not establish an average durable effect.':'Registration and nationality are distinct, and certificates alone do not remove all barriers.'} ${refs(x==='support'?['PLH']:x==='school'?['GST17','GST24']:['BIRTH24','CRVS'])}</div>`;}
function evidence(){return heading('Trace claims to their sources','Evidence matrix','Study design, setting and limitations matter more than a single confidence score. Operational suggestions are labelled separately.')+`<div class="row spaced">${badge('Evidence','evidence')}${badge('Inference','inference')}${badge('Heuristic')}${badge('User-entered','user')}</div><div class="table-wrap"><table><thead><tr><th>Claim / source</th><th>Finding</th><th>Type and context</th><th>Limitations</th></tr></thead><tbody>${D.claims.map(c=>`<tr><td>${e(c.id)}<br>${refs([c.source])}</td><td>${e(c.text)}</td><td>${e(c.strength)}<br><small>${e(c.scope)}</small></td><td>${e(c.caveat)}</td></tr>`).join('')}</tbody></table></div><h2>What this does not establish</h2>${list(['No strategy is proven to end oppression, guarantee safety or work across all African countries.','Violence-prevention results are not direct evidence of effects on racism, persecution or every form of exclusion.','A directory entry establishes a published reference, not current capacity, eligibility or quality.','A pledge or evaluation plan is not an achieved result.','The review includes recent and foundational sources but is not a systematic review or meta-analysis.'])}`;}
function research(target){return heading('Provenance and review','Research ledger','Primary-source links, publication dates, study designs, limitations and connections to strategies. Source review cutoff: 29 September 2026.')+`<div class="callout">Scope gaps: the Foundry HTML and full earlier chat were unavailable. Some sources were reviewed through publisher/search extracts; the 2025 birth-registration PDF could not be fetched. No fabricated feature audit or full-text review is claimed.</div><details><summary>Add your own research note</summary><p>${badge('User-entered / unverified','user')}This does not modify the curated evidence matrix.</p><form id="ledger-form"><label for="ledger-title">Source title</label><input id="ledger-title" name="title" maxlength="160" required><label for="ledger-url">HTTPS source URL</label><input id="ledger-url" name="url" type="url" pattern="https://.*" maxlength="1000" required><label for="ledger-date">Publication date or Unknown</label><input id="ledger-date" name="date" maxlength="40" required><label for="ledger-design">Study design / source type</label><input id="ledger-design" name="design" maxlength="160" required><label for="ledger-scope">Geography and population</label><input id="ledger-scope" name="scope" maxlength="160" required><label for="ledger-finding">Finding (no personal stories)</label><textarea id="ledger-finding" name="finding" maxlength="1200" required></textarea><label for="ledger-limit">Limitations and review depth (full text, abstract or extract)</label><textarea id="ledger-limit" name="limit" maxlength="1200" required></textarea><button class="primary">Save unverified note</button></form></details>${state.ledger.length?`<h2>Your unverified entries</h2>${state.ledger.map((l,i)=>`<article class="card spaced">${badge(l.kind,'user')}<h3>${e(l.title)}</h3><p>${e(l.finding)}</p><p>Limitations: ${e(l.limit)}</p><small>${e(l.design)} · ${e(l.scope)} · ${e(l.date)}</small><a href="${attrs(l.url)}" target="_blank" rel="noopener noreferrer">Open user-entered source ↗</a> ${button('Delete entry','delete-ledger',i)}</article>`).join('')}`:''}<h2>Curated sources</h2><div class="grid two">${D.sources.map(sourceCard).join('')}</div>`;}
function monitor(){return heading('Learn without collecting cases','Monitoring & learning','Record only non-identifying aggregate programme measures. The calculator suppresses small cells but cannot establish that a dataset is anonymous.')+`<div class="callout warning">Do not enter a value if the group, time period or surrounding information could identify a child. Do not collect new child data just to fill this form. Research with children requires appropriate ethical, legal and safeguarding review.</div><div class="grid two"><section class="card"><h3>Define a measure</h3><form id="metric-form"><label for="metric-type">Programme measure</label><select id="metric-type" name="type">${options(['Access','Referral completion','Delivery quality','Unintended barriers'])}</select><label for="metric-period">Month</label><input id="metric-period" name="period" type="month" required><label for="metric-n">Numerator (whole number)</label><input id="metric-n" name="n" type="number" min="0" max="10000000" step="1" required><label for="metric-d">Denominator (at least 10)</label><input id="metric-d" name="d" type="number" min="10" max="10000000" step="1" required><label class="inline"><input name="safe" type="checkbox" required><span>I checked that this aggregate is appropriate to store and does not expose individuals.</span></label><button class="primary">Save aggregate</button></form></section><section class="card"><h3>Use a balanced set</h3>${list(['Outcome: access to the intended service or sustained participation.','Process: completed delivery, supervision or verified referrals.','Balancing: retaliation, hidden costs, exclusion or additional burden.','Context: missing data, changed eligibility, service closures and who was not reached.'])}<p>Counts alone cannot establish impact. Suppression below five in either outcome cell is a display heuristic, not a privacy guarantee. Raw aggregates remain in backups.</p>${refs(['WHOIND','GST24'])}</section></div><h2>Your aggregate log</h2>${state.metrics.length?`<div class="table-wrap"><table><thead><tr><th>Period</th><th>Measure</th><th>Descriptive result</th><th>Action</th></tr></thead><tbody>${state.metrics.map((m,i)=>`<tr><td>${e(m.period)}</td><td>${e(m.type)} ${badge('User-entered','user')}</td><td>${m.n<5||m.d-m.n<5?'Small cell suppressed':`${m.n}/${m.d} · ${(m.n/m.d*100).toFixed(1)}%`}</td><td>${button('Delete','delete-metric',i)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No measures entered. Example only: 24 of 30 programme referrals accepted = 80%; this says nothing about the safety or quality of care.</p>'}`;}
function guides(){return heading('Plain-language methods','Practical & advanced guides','Use these as prompts for informed local work. They are planning heuristics, not professional qualifications or complete intervention manuals.')+D.guides.map(g=>`<details id="guide-${g.id}"><summary>${e(g.title)}</summary>${badge(g.kind)}<p>${e(g.body)}</p></details>`).join('')+`<p><a href="docs/handbook.html" target="_blank">Open full printable handbook ↗</a></p>`;}
function assistant(){return heading('Learning support, with or without AI','Learning assistant','The default guide is deterministic and fully local. Optional AI explains public strategy text; it cannot assess cases, contact anyone or execute actions.')+`<label for="assistant-strategy">Choose a public strategy</label><select id="assistant-strategy">${D.strategies.map(s=>`<option value="${s.id}">${e(s.title)}</option>`).join('')}</select><div class="row spaced">${button('Show reliable strategy guide','deterministic','','primary')}</div><pre id="assistant-output" aria-live="polite">Choose a strategy and open its guide.</pre><details><summary>Optional WebLLM — requires downloads and compatible hardware</summary><p>Loading the runtime contacts esm.sh. Loading a model can download hundreds of MB or more from model and runtime hosts, including Hugging Face and GitHub-hosted assets. The hosts see network metadata. Model inference is local. Model files are not in this ZIP.</p><p><strong>Recommendation heuristic:</strong> if memory is unknown or below 4 GB, stay with the deterministic guide. With a compatible WebGPU adapter, adequate free storage and memory headroom, start with the smallest 0.5B model offered. Device memory is not GPU VRAM; loading may still fail.</p><div class="row">${button('Check hardware','ai-diagnostics')}${button('Load optional runtime from CDN','load-runtime')}</div><pre id="ai-status" aria-live="polite">Runtime not loaded. No model downloads have started.</pre><label for="model">Model (IDs and memory estimates supplied by WebLLM)</label><select id="model" ${modelList.length?'':'disabled'}>${modelList.length?modelList.map(m=>`<option value="${attrs(m.model_id)}">${e(m.model_id)} · ${e(m.vram_required_MB??'?')} MB reported VRAM</option>`).join(''):'<option>Load runtime to see compatible catalogue entries</option>'}</select><div class="row spaced">${button('Download and load selected model','load-model')}${button('Generate unverified explanation','ai-explain')}${button('Unload model','unload-model')}</div><p>Generated output can be wrong, biased or incomplete. Review the cited strategy and sources. No free-text case prompt is accepted. Unloading releases runtime resources; it does not necessarily erase downloaded model caches.</p>${refs(['WEBLLM'])}</details>`;}
function collaborate(){return heading('Share a plan, deliberately','Collaboration room','Share only catalogue strategy choices. Private notes, measures, research entries, acknowledgements and task progress never enter a collaboration snapshot.')+`<div class="callout warning">Online mode uses public signalling and WebRTC. Room secrets do not verify identity, and peers or providers may observe network metadata. This is for non-sensitive programme planning, never child cases. Local mode works only between tabs on the same browser origin.</div><div class="grid two"><section class="card"><label for="room-mode">Connection mode</label><select id="room-mode"><option value="local">Local tabs — no external network</option><option value="online">Online — optional Trystero / WebRTC</option></select><label for="room-code">Random room code (16–80 characters)</label><input id="room-code" maxlength="80" autocomplete="off"><p>${button('Generate a room code','room-code')}</p><label for="room-password">Online room password (at least 16 characters)</label><input id="room-password" type="password" autocomplete="new-password" maxlength="200"><label class="inline"><input id="network-consent" type="checkbox"><span>I understand this mode’s network exposure and will share only non-sensitive catalogue choices.</span></label><div class="row spaced">${button('Join room','join-room','','primary')}${button('Disconnect','leave-room')}</div></section><section class="card"><h3>Protocol & sharing status</h3><p id="peer-status" aria-live="polite">${e(O.status())}. No content is sent automatically.</p><p>App protocol ${C.PROTOCOL} · data schema ${C.VERSION}. Incompatible messages are rejected. Late joiners receive a snapshot only when someone explicitly shares it.</p>${button('Preview snapshot to share','share-preview')}<h3>Incoming snapshot</h3><div id="incoming">${incoming?incomingView():'Nothing received.'}</div></section></div><p>There is no silent merge. Applying a snapshot replaces only your selected strategies after review, resets readiness checks and clears step completion. Your notes, measures and research entries stay local.</p>${refs(['TRYSTERO'])}`;}
function incomingView(){return `<p>${incoming.plan.length} strategy choices · sender revision ${incoming.revision}</p>${list(incoming.plan.map(id=>D.strategies.find(s=>s.id===id).title))}${button('Review replacement','apply-snapshot')}`;}
function settings(){return heading('Your device, your choices','Settings & portability','Core storage stays on this browser. It is not encrypted, and anyone with access to this browser profile may be able to read it.')+`<div class="grid two"><section class="card"><h3>Reading preferences</h3><label for="theme">Appearance</label><select id="theme" data-setting="theme">${options(['system','light','dark'],state.settings.theme)}</select><label class="inline"><input type="checkbox" data-setting="motion" ${state.settings.motion?'checked':''}><span>Reduce motion (system preference is also respected)</span></label><label class="inline"><input type="checkbox" data-setting="engagement" ${state.settings.engagement?'checked':''}><span>Show progress constellation and practice XP</span></label><p>Keyboard navigation, native collapsibles, visible focus, mobile navigation and print layouts are included. Interface language: English. Translation requires human review; no unverified automatic translation is offered.</p></section><section class="card"><h3>Backups & migration</h3><p>Schema ${C.VERSION}. Imports from versions 1 and 2 are migrated. Unknown future versions are rejected. A JSON export includes your notes and raw aggregate measures; protect the file.</p><div class="row">${button('Export JSON','export','','primary')}${button('Create local backup','backup')}${button('List backups','backups')}</div><label for="import-file">Import JSON (maximum 1 MB)</label><input id="import-file" type="file" accept="application/json,.json"><div id="backup-list"></div></section></div><section class="card spaced"><h3>Offline installation</h3><p>Open on HTTPS (GitHub Pages) or localhost and let the core cache finish. Reopen once, then test without internet. Use your browser’s Install app or Add to home screen action if available. Direct file opening supports reading and many core controls, but not service workers.</p><div class="row">${button('Request persistent storage','persist')}${button('Refresh diagnostics','goto-diagnostics')}</div><small>Browser eviction, private mode and storage quotas can still affect availability.</small></section><section class="card spaced"><h3>Reset this workspace</h3><p>Clears this app’s local planning data and internal backups. Exported files, browser history and optional model caches are separate. Other open tabs may retain old data; close them first.</p>${button('Erase planning data','erase','','danger')}</section>`;}
function diagnosticsView(){return heading('Know what works on this device','Diagnostics','Checks stay on this device. No fingerprint, device identifier or result is sent anywhere.')+`<div class="row spaced">${button('Run capability checks','diagnostics','','primary')}${button('Check core offline cache','cache-check')}${button('Check for app update','update-sw')}</div><pre id="diagnostics-output" aria-live="polite">${diagnostic?e(JSON.stringify(diagnostic,null,2)):'Run checks to inspect storage, offline support, WebGPU and collaboration availability.'}</pre><div class="grid two"><section class="card"><h3>When WebLLM fails</h3><p>Keep the deterministic guide. Check secure context, WebGPU adapter, available memory, disk, model licence and download access. A visible API does not prove model compatibility. Browser or GPU-driver updates can change support.</p></section><section class="card"><h3>When peers cannot connect</h3><p>Verify matching room code, password, app protocol and schema. Networks may block WebRTC; no TURN service is configured here. Disconnect and use local tabs or a reviewed JSON exchange. Never weaken privacy to force a connection.</p></section><section class="card"><h3>When storage fails</h3><p>Use Export JSON before closing. Private browsing, quotas or permissions may prevent persistence. Import on a trusted device after checking the backup preview. No automatic cloud backup exists.</p></section><section class="card"><h3>When offline content is missing</h3><p>Load once online, wait for cache installation and reload. The core cache excludes optional CDN runtimes, model weights and external research pages. Cached references can become stale.</p></section></div>`;}
function about(){return heading('Transparent scope','Built for careful local adaptation','A broad, curated working bundle. It cannot be exhaustive across every country, research domain or individual circumstance.')+`<div class="grid two"><section class="card"><h3>Included</h3>${list(['36 strategies across safety, racism, discrimination, violence, documentation, displacement, digital harm, participation and accountability.','27 curated sources, 25 traceable claims, 26 infrastructure entries and 26 practical guides.','Local planning, imports/exports, schema migration, backups, offline caching and optional collaboration/AI.'])}</section><section class="card"><h3>Known gaps</h3>${list(['Foundry HTML not available: no inspection, code reuse or feature-by-feature comparison claimed.','Prior conversation available only as a cached preview; the original complete HTML was not recovered.','Not a systematic review, live directory, country-specific legal guide, clinical service or case-management system.','No promise of zero harm: the design reduces certain risks but requires human safeguarding governance.'])}</section></div><h2>Documentation</h2><div class="row"><a class="button" href="README.md">README</a><a class="button" href="docs/DEPLOYMENT.md">Deployment</a><a class="button" href="docs/TEST-REPORT.md">Actual test report</a><a class="button" href="docs/TEST-CHECKLIST.md">Test checklist</a><a class="button" href="docs/ATTRIBUTIONS.md">Attributions & licences</a><a class="button" href="docs/ZERO-HARM.md">Safeguarding design</a><a class="button" href="docs/FEATURE-AUDIT.md">Feature coverage</a><a class="button" href="docs/handbook.html">Printable handbook</a></div><h2>Provenance policy</h2><p>Evidence cards paraphrase cited sources. Strategy steps are editorial inferences. Tiers, timelines, readiness, XP and cascade maps are heuristics. All notes and progress remain user-entered. No model output is promoted into the curated evidence base.</p><p>Original application code is MIT-licensed; original written guidance is CC BY 4.0. Third-party sources, software and model weights retain their own terms. Links do not imply endorsement. No third-party report text or model weights are bundled.</p>`;}
function search(q){route='search';nav();const lower=q.toLowerCase(),groups=[['Strategies',D.strategies,'strategies','title'],['Sources',D.sources,'research','title'],['Infrastructure',D.infrastructures,'infrastructure','name'],['Guides',D.guides,'guide','title']];main.innerHTML=heading('Search the whole bank','Results for “'+q+'”')+groups.map(([title,a,r,key])=>{const hits=a.filter(x=>JSON.stringify(x).toLowerCase().includes(lower));return `<h2>${title} <small style="display:inline">${hits.length}</small></h2>${hits.slice(0,50).map(x=>`<div class="card spaced"><h3><a href="#${r}/${x.id}">${e(x[key])}</a></h3><p>${e(x.goal??x.finding??x.access??x.body)}</p></div>`).join('')||'<p>No matches.</p>'}`;}).join('');}
function render(){const [id,target]=(location.hash.slice(1)||'home').split('/');route=R.some(x=>x.id===id)?id:'home';if(route==='strategies'&&target)filter={domain:'All',tier:'All',role:'All'};nav();applySettings();const views={home,safety,strategies,plan,infrastructure,pathways,maps,evidence,research,monitor,guide:guides,assistant,collaborate,settings,diagnostics:diagnosticsView,about};main.innerHTML=views[route](target);document.title=(R.find(x=>x.id===route)?.label??'Start')+' · Safeguard Africa';closeDrawer();if(route==='maps')cascade();if(target){const prefix={strategies:'strategy-',infrastructure:'infra-',research:'source-',guide:'guide-'}[route];const el=prefix?document.getElementById(prefix+target):null;if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({block:'start'});}}}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal();}
function currentStrategy(){return D.strategies.find(x=>x.id===$('#assistant-strategy').value);}
const triage={urgent:'If safe, seek appropriate urgent local health or emergency help now. Avoid confronting an alleged perpetrator. If the usual authority is implicated or unsafe, seek an independent trusted protection provider. This app cannot dispatch help.',disclosure:'Listen calmly without blame, leading questions or forced retelling. Explain confidentiality limits and seek trained support through a verified safe channel. Do not automatically notify an implicated caregiver or institution.',access:'Identify the specific access barrier, ask what remedy the child wants, and check safe local school, legal-aid or service-review routes. Begin with one strategy and an anti-retaliation review.',planning:'Choose one strategy, verify the relevant infrastructure, review prerequisites and stop rules, then agree responsibilities, resources and a review date. Use only non-identifying programme notes.'};
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;try{
 if(a==='toggle-plan'){if(state.plan.includes(v)){state.plan=state.plan.filter(x=>x!==v);for(const k of Object.keys(state.tasks))if(k.startsWith(v+':'))delete state.tasks[k];}else state.plan.push(v);state.gates=[];await save();render();notice('Plan updated. Review the readiness checks after changing scope.');}
 if(a==='triage')$('#triage-result').innerHTML=`<div class="callout">${triage[v]}</div><a href="#strategies/${v==='urgent'||v==='disclosure'?'S01':v==='access'?'S03':'S27'}">Open relevant strategy →</a>`;
 if(a==='save-note'){state.notes=$('#plan-notes').value;await save();notice('Programme note saved locally.');}
 if(a==='review-plan'){const p=C.progress(state,D);modal(p.canReview?'<h2>Ready for human review</h2><p>Your preparation checks are acknowledged. This is not a safety certification or permission to act. Review the child’s preferences, local rules, provider capacity and stop decisions with the appropriate responsible person.</p><p>Nothing has been sent or executed.</p>':'<h2>Preparation is incomplete</h2><p>Select at least one strategy and acknowledge all four readiness checks. Do not postpone urgent help to complete this planner.</p>');}
 if(a==='export'){download('safeguard-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));notice('JSON export created. It includes your notes and raw aggregate data; keep it protected.');}
 if(a==='backup'){await S.backup(state);notice('Local snapshot saved. The most recent five internal backups are retained.');}
 if(a==='backups'){const keys=await S.list();$('#backup-list').innerHTML='<h4>Internal backups</h4>'+(keys.map(k=>`<p>${e(k)} ${button('Preview restore','restore',k)}</p>`).join('')||'<p>No internal backups.</p>');}
 if(a==='restore'){pendingImport=C.migrate(await S.get(v),D);previewImport();}
 if(a==='confirm-import'){const old=structuredClone(state);if(S.mode()==='IndexedDB')await S.backup(old);state=pendingImport;pendingImport=null;await save();$('#modal').close();render();notice('Validated backup applied. Review local context before action.');}
 if(a==='persist'){notice(await navigator.storage?.persist?.()?'Persistent storage granted; still keep backups.':'Persistent storage was not granted or is unavailable. Keep JSON backups.');}
 if(a==='erase')modal('<h2>Erase local planning data?</h2><p>This also removes this app’s internal backups. Export first if needed. Close other tabs to avoid old data being saved again.</p>'+button('Erase now','confirm-erase','','danger'));
 if(a==='confirm-erase'){await saveQueue;await S.clear();state=C.fresh();await save();$('#modal').close();render();notice('Local planning data and internal backups cleared. Exported files, history and model caches are separate.');}
 if(a==='delete-ledger'){state.ledger.splice(+v,1);await save();render();}
 if(a==='delete-metric'){state.metrics.splice(+v,1);await save();render();}
 if(a==='goto-diagnostics')location.hash='diagnostics';
 if(a==='diagnostics'||a==='ai-diagnostics'){diagnostic=await O.diagnostics();(a==='diagnostics'?$('#diagnostics-output'):$('#ai-status')).textContent=JSON.stringify(diagnostic,null,2);}
 if(a==='cache-check'){const keys='caches'in globalThis?await caches.keys():[];const ours=keys.filter(k=>k.startsWith('safeguard-africa-'));const counts=await Promise.all(ours.map(async k=>({cache:k,entries:(await (await caches.open(k)).keys()).length})));$('#diagnostics-output').textContent=JSON.stringify({controlled:!!navigator.serviceWorker?.controller,caches:counts,note:'Cache presence is not an offline reload test.'},null,2);}
 if(a==='update-sw'){const reg=await navigator.serviceWorker?.getRegistration();if(reg){await reg.update();notice('Update check requested. Close and reopen all tabs to activate a waiting version.');}else notice('No service worker registered. Use HTTPS or localhost.');}
 if(a==='deterministic')$('#assistant-output').textContent=C.guide(currentStrategy());
 if(a==='load-runtime'){b.disabled=true;$('#ai-status').textContent='Loading optional runtime…';try{modelList=await O.loadRuntime();$('#model').innerHTML=modelList.map(m=>`<option value="${attrs(m.model_id)}">${e(m.model_id)} · ${e(m.vram_required_MB??'?')} MB reported VRAM</option>`).join('');$('#model').disabled=false;$('#ai-status').textContent='Runtime loaded. Select a model and explicitly start its download.';}finally{b.disabled=false;}}
 if(a==='load-model'){b.disabled=true;try{await O.loadModel($('#model').value,t=>{if($('#ai-status'))$('#ai-status').textContent=t;});if($('#ai-status'))$('#ai-status').textContent='Model loaded. Outputs remain unverified.';}finally{b.disabled=false;}}
 if(a==='ai-explain'){b.disabled=true;const chosen=currentStrategy();try{$('#assistant-output').textContent='Generating an unverified learning draft…';const result=await O.explain(chosen);if($('#assistant-output'))$('#assistant-output').textContent='UNVERIFIED AI DRAFT — check against sources and deterministic guide\n\n'+result;}finally{b.disabled=false;}}
 if(a==='unload-model'){await O.unload();$('#ai-status').textContent='Model unloaded. Downloaded caches may remain in browser storage.';}
 if(a==='room-code')$('#room-code').value=crypto.randomUUID().replaceAll('-','');
 if(a==='join-room'){if(!$('#network-consent').checked)throw Error('Acknowledge the selected mode’s sharing boundaries first.');b.disabled=true;try{await O.join($('#room-mode').value,$('#room-code').value,$('#room-password').value,(snap)=>{incoming=snap;if($('#incoming'))$('#incoming').innerHTML=incomingView();notice('Incoming catalogue snapshot received. Review before applying.');},msg=>{if($('#peer-status'))$('#peer-status').textContent=msg;});}finally{b.disabled=false;}}
 if(a==='leave-room')O.leave();
 if(a==='share-preview'){const snap=C.snapshot(state);modal('<h2>Share these catalogue choices?</h2><p>Only these strategy IDs and protocol metadata will be sent. No notes, tasks, gates, measures or research entries are included.</p>'+list(snap.plan.map(id=>D.strategies.find(s=>s.id===id).title))+button('Send reviewed snapshot','send-snapshot','','primary'));}
 if(a==='send-snapshot'){await O.share(C.snapshot(state));$('#modal').close();}
 if(a==='apply-snapshot'){if(!incoming)throw Error('No incoming snapshot');modal('<h2>Replace selected strategies?</h2><p>Your current strategy choices and completion checks will be replaced. Readiness acknowledgements reset. Notes and other local records remain.</p>'+list(incoming.plan.map(id=>D.strategies.find(s=>s.id===id).title))+button('Apply reviewed snapshot','confirm-snapshot','','primary'));}
 if(a==='confirm-snapshot'){if(S.mode()==='IndexedDB')await S.backup(state);state.plan=[...incoming.plan];state.tasks={};state.gates=[];incoming=null;await save();$('#modal').close();render();notice('Reviewed strategy choices applied. Preparation checks reset.');}
}catch(err){notice(err.message);if($('#ai-status')&&['load-runtime','load-model','ai-explain'].includes(a))$('#ai-status').textContent='Optional AI failed: '+err.message+'. The deterministic guide remains available.';if(a==='join-room'){O.leave();if($('#peer-status'))$('#peer-status').textContent='Connection failed: '+err.message+'. Use local mode or JSON exchange.';}}});
function previewImport(){modal(`<h2>Replace local workspace with this backup?</h2><p>Schema ${pendingImport.schema} · ${pendingImport.plan.length} strategies · ${pendingImport.metrics.length} aggregate measures · ${pendingImport.ledger.length} unverified sources · ${pendingImport.notes.length} note characters.</p><p>Current state will be saved as an internal backup if IndexedDB is available. Text remains unverified user content. No code or external links are executed by importing.</p>${button('Apply validated backup','confirm-import','','primary')}`);}
document.addEventListener('change',async ev=>{const t=ev.target;try{
 if(t.dataset.gate){state.gates=t.checked?[...state.gates,t.dataset.gate]:state.gates.filter(x=>x!==t.dataset.gate);await save();const p=C.progress(state,D);if($('progress')){$('progress').value=p.readiness;$('progress').nextElementSibling.textContent=p.readiness+'% of preparation checks acknowledged · heuristic, not a risk score';}}
 if(t.dataset.task){state.tasks[t.dataset.task]=t.checked;await save();render();}
 if(t.dataset.setting){const key=t.dataset.setting;if(key==='role')state.role=t.value;else state.settings[key]=t.type==='checkbox'?t.checked:t.value;await save();if(key==='role')render();else applySettings();}
 if(t.dataset.filter){filter[t.dataset.filter]=t.value;render();}
 if(t.id==='cascade-select')cascade();
 if(t.id==='plan-notes'){state.notes=t.value;await save();}
 if(t.id==='import-file'){const file=t.files[0];if(!file)return;if(file.size>1000000)throw Error('Backup exceeds 1 MB');pendingImport=C.parseImport(await file.text(),D);previewImport();t.value='';}
}catch(err){notice('No import applied: '+err.message);}});
document.addEventListener('input',ev=>{if(ev.target.id==='infra-query'){const q=ev.target.value.toLowerCase();document.querySelectorAll('[data-infra]').forEach(el=>el.hidden=!el.dataset.infra.includes(q));}});
document.addEventListener('submit',async ev=>{if(!['ledger-form','metric-form'].includes(ev.target.id))return;ev.preventDefault();try{const f=Object.fromEntries(new FormData(ev.target));const next=structuredClone(state);if(ev.target.id==='ledger-form')next.ledger.push(f);else next.metrics.push({type:f.type,period:f.period,n:Number(f.n),d:Number(f.d)});state=C.migrate(next,D);await save();render();notice('User-entered record saved locally.');}catch(err){notice(err.message);}});
$('#search').addEventListener('input',ev=>{clearTimeout(searchTimer);const q=ev.target.value.trim();searchTimer=setTimeout(()=>q?search(q):render(),180);});
$('#menu').addEventListener('click',()=>{const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#sidebar').inert=!open;$('#menu').setAttribute('aria-expanded',String(open));if(open)$('#sidenav a').focus();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeDrawer();$('#splash')?.remove();}if(ev.key==='Tab'&&innerWidth<=850&&$('#sidebar').classList.contains('open')){const links=[...$('#sidebar').querySelectorAll('a')];if(ev.shiftKey&&document.activeElement===links[0]){ev.preventDefault();$('#menu').focus();}else if(!ev.shiftKey&&document.activeElement===links.at(-1)){ev.preventDefault();$('#menu').focus();}}});
$('.skip').addEventListener('click',ev=>{ev.preventDefault();main.focus();});
$('#print').addEventListener('click',()=>{document.querySelectorAll('main details').forEach(x=>x.open=true);window.print();});
$('#exit').addEventListener('click',()=>{O.leave();document.body.innerHTML='<main style="padding:40px;font-family:system-ui"><h1>Workspace closed</h1><p>This screen is clear. Browser history and saved data have not been erased.</p></main>';document.title='Workspace';});
window.addEventListener('hashchange',()=>{$('#search').value='';render();main.focus({preventScroll:true});});
window.addEventListener('resize',()=>{$('#sidebar').inert=innerWidth<=850&&!$('#sidebar').classList.contains('open');});
const connection=()=>$('#connection').textContent=navigator.onLine?'Local-first · online':'Offline';window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applySettings);
try{const loaded=await S.init();if(loaded)state=C.migrate(loaded,D);}catch(err){notice('Stored state could not be loaded: '+err.message+'. Existing storage was not overwritten.');}
$('#storage-status').textContent=S.mode()==='IndexedDB'?'Saved on this device':'Memory only — export before closing';render();
$('#splash')?.addEventListener('click',()=>$('#splash')?.remove());setTimeout(()=>$('#splash')?.remove(),1400);
if('serviceWorker'in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{if(!storageProblem)$('#storage-status').textContent=(S.mode()==='IndexedDB'?'Local storage ready':'Memory only')+' · offline cache installed';}).catch(err=>notice('Offline installation unavailable: '+err.message+'. Core tools remain usable online.'));}
globalThis.SG_APP={getState:()=>structuredClone(state),render};
})();
